window.__posterData({"id": "anahi-pabon-reyes", "name": "Anahi Pabon Reyes", "folder": "Week1_Poster_with_AI__Anahi_Pabon_Reyes", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "/* ============================================================\n   SKOGSRAVE – stil för postersidan\n   Refaktorerad: samma regler som originalet, bara städad format.\n   ============================================================ */\n\n/* Nollställer webbläsarens marginaler så att duken ligger slätt mot kanterna */\nhtml,\nbody {\n  margin: 0;\n  padding: 0;\n}\n\n/* Tar bort mellanrummet under canvasen (inline-elementets baseline) */\ncanvas {\n  display: block;\n}", "code": "// Alla kommenatrer som är inom \"===\" är Ais kommentarer som jag anser har varit nödvändiga att behålla, för att förstå själv eller för att jag anser att deras förklaring är tydligare än mina egna. \n//\n// första delen av uppgiften har Ai sorterat min kod så att det blir sammanhängande och får en tydligare struktur. De flesta variablar gjorde AI om så att de definerades av konstanter (const), små funktioner och konsekvent stil.\n//\n//============================================================\n// DEL 2 AV UPPGIFTEN (\"välj ett element och ändra det\"):\n// Elementet = cirkel-ringarna. De är nu en familj där varje cirkel är\n// större än den förra, och när musen hålls ner vandrar en rosa \"eko\"-våg\n// genom dem, cirkel för cirkel. Rubriken SKOGSRAVE tänder som ekots\n// sista steg. Släpper man musen går allt tillbaka till blått (royalblue).\n//\n// DEL 3 AV UPPGIFTEN (AI:ns egen idé): ELDFLUGOR\n// Lysande prickar i posterns färger svävar runt i skogen och flimrar.\n// Rör man musen över postern samlas de i en svärm runt muspekaren.\n// =====================================================================\n \n// bakgrundsbild\nlet img; \n\n//Detta var en av funktionerna jag bad AI att göra eftersom jag alltid ville ha en en echo effekt med cirklar men var osäker man gick till vägas.\n//== Ekots tillstånd: frameCount när musen trycktes ner (null = inget eko pågår)==\nlet echoStart = null;\n \n// Eldflugorna: en lista med objekt (position, storlek, färg ...)\nlet fireflies = [];\n \n// ---------- Text längst ner på postern (ARRAY) ----------\nconst CREDITS = ['ANAHI PABON REYES', 'SÖDERTÖRNS HÖGSKOLA'];\n \n// ---------- Konstanter: alla \"magiska siffror\" bor här ----------\nconst CANVAS_WIDTH = 600;  // arbetsytans bredd\nconst CANVAS_HEIGHT = 800; // arbetsytans höjd\n \nconst PINK = [255, 0, 127];    // posterns signaturrosa\nconst WHITE = [255, 255, 255]; // blinkfärgen vitt\nconst BLUE = [65, 105, 225];   // royalblue som RGB (för eldflugorna)\nconst TITLE = 'SKOGSRAVE';\n \n// Cirkelfamiljen (det utvalda elementet). De två första är originalcirklarna,\n// varje ny cirkel är 50 px större än den förra. Största cirkeln slutar på\n// x ≈ 141 och når aldrig rubriken (vars bokstäver slutar på x ≈ 115).\nconst RINGS = [\n  { x: 365, y: 400, size: 300 }, // originalets inre cirkel\n  { x: 367, y: 400, size: 350 }, // originalets yttre cirkel\n  { x: 366, y: 400, size: 400 }, // ny cirkel\n  { x: 366, y: 400, size: 450 }, // ny cirkel – störst\n];\n \n// Ekot: vågens färg, vilofärgen och hur ofta vågen går ett steg framåt\nconst ECHO_COLOR = 'deeppink';  // samma rosa som tryckfärgen i originalet\nconst REST_COLOR = 'royalblue'; // samma blå som släppfärgen i originalet\nconst ECHO_STEP = 10;           // var 10:e frame tänder nästa cirkel\n \n// Eldflugorna (del 3)\nconst FIREFLY_COUNT = 40;                    // hur många eldflugor\nconst FIREFLY_COLORS = [PINK, BLUE, WHITE];  // posterns egna färger\nconst FIREFLY_SPEED = 0.6;                   // hur fort de svävar\nconst FIREFLY_PULL = 0.04;                   // hur hårt musen drar i dem\nconst FIREFLY_FLICKER = 0.1;                 // hur fort de flimrar\n \n// rubrikens utseende och placering\nconst TITLE_STYLE = { x: 50, y: 140, size: 80, rotation: 90, weight: 8 };\n \n// nedre texternas utseende och placering\nconst CREDIT_STYLE = { x: 30, y: 700, size: 18, lineHeight: 35, weight: 2 };\n \n// Blinkrytm: färgen växlar var 30:e frame => två ggr per sekund (60 fps)\nconst BLINK_CYCLE = 60;\n \n// Pennlägen som musen styr\nconst PRESSED_WEIGHT = 3;  // konturtjocklek när musknappen trycks ner\nconst CLICKED_WEIGHT = 10; // konturtjocklek vid click\nconst RING_WEIGHT = CLICKED_WEIGHT; // cirklarnas tjocklek från start (inget klick behövs)\n \n// ---------------------------------------------------------------------\n// setup – körs en gång: bild, arbetsyta och eldflugor\n// ---------------------------------------------------------------------\nasync function setup() {\n  img = await loadImage('skograve.jpg'); // hämtar bilden\n \n  createCanvas(CANVAS_WIDTH, CANVAS_HEIGHT); // arbetsytan\n \n  describe('Bild på en lysande människa i en skog'); // beskrivning\n  describe('Text skogs rave som titel');             // beskrivning av rubriken\n \n  createFireflies(); // släpper ut eldflugorna i skogen\n \n  // cirklarna syns direkt: samma tjocklek som efter ett klick\n  strokeWeight(RING_WEIGHT);\n}\n \n// ---------------------------------------------------------------------\n// draw – funktion som kör om och om igen\n// Bilden och rubriken ritas om varje frame – annars skulle eldflugorna\n// lämna spår efter sig över hela postern.\n// ---------------------------------------------------------------------\nfunction draw() {\n  image(img, 0, 0); // visar bilden (målar över förra framen)\n  drawTitle();      // rubriken i svart\n \n  drawRings();      // ringfamiljen med ekot (del 2)\n  drawTitleEcho();  // rubriken tänder som ekots sista steg\n  drawCredits();    // blinkande texter – oförändrat\n  drawFireflies();  // eldflugorna svävar överst (del 3)\n}\n \n// ==================== Hjälpfunktioner: posterns delar ====================\n \n// Vågfronten: hur många cirklar ekot hunnit passera (växer varje frame).\n// Returnerar -1 när inget eko pågår.\nfunction echoWave() {\n  if (echoStart === null) return -1;\n  return (frameCount - echoStart) / ECHO_STEP;\n}\n \n// Ringfamiljen: vilar i blått, och när musen hålls ner vandrar en rosa\n// eko-våg utåt, cirkel för cirkel (innerst → ytterst).\nfunction drawRings() {\n  const wave = echoWave(); // hur långt vågen hunnit\n \n  noFill(); // cirklarna är bara konturer – aldrig fyllda\n \n  for (let i = 0; i < RINGS.length; i++) {\n    if (i < wave) {\n      stroke(ECHO_COLOR); // vågen har nått cirkeln → rosa\n    } else {\n      stroke(REST_COLOR); // vågen är inte framme än → blått\n    }\n    // Konturtjockleken ärver pennan: tryck = 3 px, click = 10 px\n    circle(RINGS[i].x, RINGS[i].y, RINGS[i].size);\n  }\n}\n \n// Ekots sista steg: när vågen passerat sista cirkeln tänder rubriken\nfunction drawTitleEcho() {\n  if (echoStart !== null && echoWave() >= RINGS.length) {\n    drawTitle(ECHO_COLOR); // rosa rubrik – tills man släpper musen\n  }\n}\n \n// Rubriken – roterad 90 grader, ritas från en flyttad origo.\n// color är 0 (svart) som default; ekot skickar in ECHO_COLOR när den tänder.\nfunction drawTitle(color = 0) {\n  push(); // sparar nuvarande inställningar\n \n  translate(TITLE_STYLE.x, TITLE_STYLE.y); // flyttar koordinatsystemet\n  rotate(radians(TITLE_STYLE.rotation));   // roterar 90 grader\n \n  textSize(TITLE_STYLE.size); // rubrikens utseende\n  fill(color);                // fyllnaden (svart – eller ekots rosa)\n  stroke(color);\n  strokeWeight(TITLE_STYLE.weight);\n \n  text(TITLE, 0, 0); // skriver rubriken – ritas vid nya origo-positionen\n \n  pop(); // återställer inställningarna från push\n}\n \n// Nedre texterna – en rad per text, färgen blinkar rosa/vit\nfunction drawCredits() {\n  push(); // sparar inställningarna innan texten ritas\n \n  textSize(CREDIT_STYLE.size); // gör texten mindre\n  textAlign(LEFT, CENTER);     // gör texten vänsterjusterad\n  stroke(0);                   // gör textens kontur svart\n  strokeWeight(CREDIT_STYLE.weight);\n \n  // for-loop: går igenom alla texter i arrayen\n  for (let i = 0; i < CREDITS.length; i++) {\n    fill(...blinkColor()); // if-statementet nedan väljer färgen\n \n    // skriver ut varje text på en egen rad\n    text(CREDITS[i], CREDIT_STYLE.x, CREDIT_STYLE.y + i * CREDIT_STYLE.lineHeight);\n  }\n \n  pop(); // återställer textens inställningar\n}\n \n// if-statement: kontrollerar vilken färg texten ska ha just denna frame\nfunction blinkColor() {\n  if (frameCount % BLINK_CYCLE < BLINK_CYCLE / 2) {\n    return PINK; // rosa\n  }\n  return WHITE;  // vitt\n}\n \n// ==================== Eldflugor (del 3) ====================\n \n// Skapar alla eldflugor med slumpad plats, storlek, färg och rytm\nfunction createFireflies() {\n  for (let i = 0; i < FIREFLY_COUNT; i++) {\n    fireflies.push({\n      x: random(width),          // startposition\n      y: random(height),\n      size: random(3, 6),        // storlek på kärnan\n      color: random(FIREFLY_COLORS), // rosa, blå eller vit\n      seed: random(1000),        // egen \"slump-väg\" för noise()\n      phase: random(TWO_PI),     // egen flimmerrytm\n      orbit: random(15, 60),     // avstånd till musen i svärmen\n    });\n  }\n}\n \n// Ritar alla eldflugor. push/pop: de får inte ändra pennan för cirklarna!\nfunction drawFireflies() {\n  push();\n  noStroke();\n  for (let i = 0; i < fireflies.length; i++) {\n    moveFirefly(fireflies[i]);\n    drawFirefly(fireflies[i]);\n  }\n  pop();\n}\n \n// Är musen över postern? (före första musrörelsen står den på 0,0)\nfunction mouseOnPoster() {\n  return mouseX > 0 && mouseX < width && mouseY > 0 && mouseY < height;\n}\n \n// Flyttar en eldfluga: mjuk slumpväg med noise(), och dras mot musen\nfunction moveFirefly(f) {\n  // noise() ger en mjuk \"slumpriktning\" som ändras långsamt\n  const angle = noise(f.seed, frameCount * 0.005) * TWO_PI * 2;\n  f.x += cos(angle) * FIREFLY_SPEED;\n  f.y += sin(angle) * FIREFLY_SPEED;\n \n  if (mouseOnPoster()) {\n    // varje eldfluga cirklar runt musen på sitt eget avstånd → en svärm\n    const targetX = mouseX + cos(f.phase + frameCount * 0.03) * f.orbit;\n    const targetY = mouseY + sin(f.phase + frameCount * 0.03) * f.orbit;\n    f.x += (targetX - f.x) * FIREFLY_PULL;\n    f.y += (targetY - f.y) * FIREFLY_PULL;\n  }\n \n  // flyger den ut ur bild kommer den in på andra sidan\n  f.x = (f.x + width) % width;\n  f.y = (f.y + height) % height;\n}\n \n// Ritar en eldfluga som ett glödande sken: stort och svagt ytterst,\n// litet och starkt i mitten. glow (0–1) får den att flimra.\nfunction drawFirefly(f) {\n  const glow = 0.5 + 0.5 * sin(frameCount * FIREFLY_FLICKER + f.phase);\n  const [r, g, b] = f.color;\n \n  fill(r, g, b, 40 * glow);  // yttre sken\n  circle(f.x, f.y, f.size * 4);\n  fill(r, g, b, 110 * glow); // inre sken\n  circle(f.x, f.y, f.size * 2);\n  fill(255, 255, 255, 230 * glow); // vit kärna\n  circle(f.x, f.y, f.size * 0.8);\n}\n \n// ==================== Musfunktioner: pennan styrs av musen ====================\n \n// trycker ner musknappen\nfunction mousePressed() {\n  stroke('deeppink');           // ändrar konturfärg\n  strokeWeight(PRESSED_WEIGHT); // gör konturen tunnare\n  echoStart = frameCount;       // startar ekot från innersta cirkeln\n}\n \n// när man släpper musen\nfunction mouseReleased() {\n  stroke('royalblue'); // blir blå\n  echoStart = null;    // ekot slutar – cirklarna och rubriken går tillbaka nästa frame\n}\n \n// vid click\nfunction mouseClicked() {\n  strokeWeight(CLICKED_WEIGHT);\n}", "assets": {"skograve.jpg": {"mime": "image/webp", "b64": ""}}});
